using System;using System.IO;using System.Drawing;using System.Drawing.Imaging;using System.Diagnostics;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Collections.Generic;using System.Text;
static class OfflineImageText {
 static readonly Dictionary<string,Dictionary<string,object>> cache=new Dictionary<string,Dictionary<string,object>>();static readonly object gate=new object();internal static async Task<Dictionary<string,object>> Recognise(Bitmap image){string folder=Path.Combine(Path.GetTempPath(),"Jago-Image-Text-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string file=Path.Combine(folder,"image.png");try{double scale=Math.Min(1,2000.0/Math.Max(image.Width,image.Height));using(var small=new Bitmap(Math.Max(1,(int)(image.Width*scale)),Math.Max(1,(int)(image.Height*scale)))){using(var g=Graphics.FromImage(small)){g.Clear(Color.White);g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;g.DrawImage(image,0,0,small.Width,small.Height);}small.Save(file,ImageFormat.Png);}string key;using(var sha=System.Security.Cryptography.SHA256.Create())key=Convert.ToBase64String(sha.ComputeHash(File.ReadAllBytes(file)));lock(gate){Dictionary<string,object> found;if(cache.TryGetValue(key,out found))return found;}string script;using(var scriptStream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("ImageTextEngine.ps1"))using(var reader=new StreamReader(scriptStream)){script=reader.ReadToEnd();};var start=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe"),"-NoProfile -NonInteractive -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes(script))){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8};start.EnvironmentVariables["JAGO_OCR_INPUT"]=file;using(var process=Process.Start(start)){Task<string> output=process.StandardOutput.ReadToEndAsync(),error=process.StandardError.ReadToEndAsync();if(!await Task.Run(()=>process.WaitForExit(45000))){try{process.Kill();}catch{}throw new Exception("Text recognition timed out. Try a smaller, clearer image.");}string text=await output,problem=await error;if(process.ExitCode!=0)throw new Exception("Windows text recognition could not run. Check that a Windows OCR language is installed. "+problem.Substring(0,Math.Min(300,problem.Length)));var result=new JavaScriptSerializer{MaxJsonLength=8000000}.Deserialize<Dictionary<string,object>>(text.Trim());lock(gate){if(cache.Count>=8)cache.Clear();cache[key]=result;}return result;}}finally{try{File.Delete(file);Directory.Delete(folder);}catch{}}}
}
